package com.example.customerrouting.simulation.banking77; import com.example.customerrouting.enquiry.*; import org.springframework.cache.annotation.*; import org.springframework.stereotype.*; @Component public class Banking77IntentMapping { @Cacheable("banking77IntentMappings") public EnquiryCategory categoryFor(String intent){String i=intent.toLowerCase(); if(i.contains("cash_withdrawal")||i.contains("cash withdrawal")||i.contains("card_swallowed")||i.contains("atm_support")) return i.contains("not_recognised")||i.contains("wrong_amount")||i.contains("declined")?EnquiryCategory.ATM_DISPUTE:EnquiryCategory.ATM_QUERY; if(i.contains("fraud")||i.contains("compromised")||i.contains("lost_or_stolen_card"))return EnquiryCategory.CARD_FRAUD; if(i.contains("card_payment_not_recognised")||i.contains("charged_twice")||i.contains("refund")||i.contains("reverted_card"))return EnquiryCategory.CARD_PAYMENT_DISPUTE; if(i.contains("transfer")||i.contains("beneficiary")||i.contains("receiving_money"))return EnquiryCategory.BANK_TRANSFER; if(i.contains("mortgage"))return EnquiryCategory.MORTGAGE_QUERY; if(i.contains("loan"))return EnquiryCategory.LOAN_QUERY; if(i.contains("verify")||i.contains("identity")||i.contains("source_of_funds"))return EnquiryCategory.IDENTITY_VERIFICATION; if(i.contains("fee")||i.contains("charge")||i.contains("exchange_rate"))return EnquiryCategory.FEES_AND_CHARGES; if(i.contains("card")||i.contains("pin")||i.contains("apple_pay")||i.contains("contactless"))return EnquiryCategory.CARD_SERVICES; if(i.contains("balance")||i.contains("account")||i.contains("cash_deposit")||i.contains("personal_details")||i.contains("passcode"))return EnquiryCategory.ACCOUNT_QUERY; return EnquiryCategory.GENERAL_BANKING;} }
